tasks = values('Allowed assignments', 'L812:L820')
workers = values('Allowed assignments', 'M812:M820')
costs = values('Allowed assignments', 'N812:N820')

all_tasks = list(set(tasks))
all_workers = list(set(workers))

min_cost = None
for w1 in all_workers:
    for w2 in all_workers:
        if w1 == w2: continue
        for w3 in all_workers:
            if w3 == w1 or w3 == w2: continue
            assignment = {all_tasks[0]: w1, all_tasks[1]: w2, all_tasks[2]: w3}
            current_cost = 0
            valid = True
            for t, w in zip(tasks, workers):
                pass
            # compute cost for this permutation
            total = 0
            possible = True
            for t_target, w_target in assignment.items():
                found = False
                for t, w, c in zip(tasks, workers, costs):
                    if t == t_target and w == w_target:
                        total += c
                        found = True
                        break
                if not found:
                    possible = False
                    break
            if possible:
                if min_cost is None or total < min_cost:
                    min_cost = total
result = min_cost

