sheet = "Transition probabilities"
rows = data_rows(sheet, {'H':'string', 'G':'number'}, 390, 398)
states = [cell(sheet, f'H{r}') for r in rows]
to_states = [cell(sheet, f'I{r}') for r in rows]
probs = [num(sheet, f'G{r}') for r in rows]

P = {}
for h, i, g in zip(states, to_states, probs):
    P[(h, i)] = g

s_list = sorted(list(set(states + to_states)))

# Step 0: Idle = 1, others = 0
v = {'Idle': 1.0, 'Active': 0.0, 'Done': 0.0}

active_visits = 0.0
for step in range(1, 4):
    next_v = {}
    for s2 in s_list:
        next_v[s2] = sum(v[s1] * P.get((s1, s2), 0.0) for s1 in s_list)
    v = next_v
    active_visits += v['Active']

result = round(active_visits, 6)
